issuers <- dir("./Data/RawData/Form D", recursive=TRUE, full.names=TRUE, pattern ="ISSUERS")
all_files <- lapply(issuers,function(x) {
  as.data.frame(fread(file = x, 
                      sep = '\t', na.strings = c("",NA," "),
                      header = TRUE))
})

